import tune
NAMES=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B']
def m(nm): return tune.N(nm)
# check lead vs harmony intervals per row for the harmony patterns
pairs={'A/A2':(tune.MEL_A,tune.MEL_A2),'A2/A':(tune.MEL_A2,tune.MEL_A),
       'B/B2':(tune.MEL_B,tune.MEL_B2),'B2/B':(tune.MEL_B2,tune.MEL_B)}
for nm,(l1,l2) in pairs.items():
    d1={r:m(n) for (r,n,d,v) in l1 if n}
    d2={r:m(n) for (r,n,d,v) in l2 if n}
    rows=sorted(set(d1)|set(d2))
    out=[]
    for r in rows:
        a=d1.get(r); b=d2.get(r)
        if a is not None and b is not None:
            iv=(a-b)%12
            out.append((r,NAMES[a%12],NAMES[b%12],iv))
    bad=[o for o in out if o[3] in (1,2,10,11)]
    print(nm, 'unison/interval rows:', [(o[0],o[1],o[2],o[3]) for o in out])
    print('   harsh intervals:', bad)
